5	/// GPU memory the EAGLE-3 draft needs on top of the target KV pool, derived from
6	/// the draft config so the KV budget can reserve it *before* the draft loads.
7	///
8	/// Split by how it's billed against the KV budget:
9	///
10	/// - `kv_bytes_per_token` — scales with the pool, billed by shrinking the target
11	///   block count. This is *only* the draft's single-layer autoregressive K/V cache.
12	///   The captured 3-layer target features are forward inputs consumed at the fusion
13	///   step, not persisted, so nothing else scales per pool token.
14	/// - `fixed_bytes` — does not scale with the pool, billed via the memory margin: the
15	///   draft weights, the batched-prefill / per-request-decode dense scratch, and the
16	///   captured-feature buffer (`[3*hidden, N]`) that feeds prefill. These are bounded
17	///   by the prefill span / decode batch, not the sequence length.
18	pub(crate) struct Eagle3MemoryReservation {
19	    pub(crate) kv_bytes_per_token: usize,
20	    pub(crate) fixed_bytes: usize,
21	}
22	
23	impl Eagle3MemoryReservation {
24	    /// Load the draft config from `model_path` and compute the reservation
25	    pub(crate) fn from_path(
26	        model_path: &str,
27	        max_prefill_tokens: usize,
28	        max_decode_batch_size: usize,
29	    ) -> Result<Self> {
30	        let config = Eagle3Config::from_file(model_path)?;
31	        Ok(Self::from_config(
32	            &config,
33	            max_prefill_tokens,
34	            max_decode_batch_size,
35	        ))
36	    }
37	
38	    pub(crate) fn from_config(
39	        config: &Eagle3Config,
40	        max_prefill_tokens: usize,
41	        max_decode_batch_size: usize,
42	    ) -> Self {
43	        const BF16: usize = 2;
44	        let kv_dim = config.num_key_value_heads * config.head_dim;
45	        let q_dim = config.num_attention_heads * config.head_dim;
46	        let hidden = config.hidden_size;
47	        let inter = config.intermediate_size;
48	        // EAGLE-3 fuses low/mid/high target hidden, so `fc` takes 3 * hidden in.
49	        let fc_in = 3 * hidden;
50	
51	        // Per-pool-token, pool-scaling: the single-layer draft K/V (k + v).
52	        let kv_bytes_per_token = config.num_hidden_layers * 2 * kv_dim * BF16;
53	
54	        // Draft weights: the `midlayer` block + `fc` + draft head + norms.
55	        // The embedding is reused from the target (the checkpoint ships none), and the
56	        // `d2t`/`t2d` tables are host-resident(CPU-side lookup at sample time)
57	        let midlayer = BF16
